field.div:
Shift ${object.status == 'cancelled' and 'Cancelled' or 'Modified'}
Hello ${object.guard_id.name},
% if object.status == 'cancelled': Your scheduled shift has been cancelled. % else: Your shift schedule has been modified. % endif
Shift Details:
Site: ${object.site_id.name}
Start: ${format_datetime(object.start_datetime, dt_format='medium')}
End: ${format_datetime(object.end_datetime, dt_format='medium')}
Status:
${object.status.replace('_', ' ').upper()}
% if object.instructions:
Notes:
${object.instructions}
% endif
% if object.status == 'cancelled':
This shift has been removed from your schedule. If you have any questions, please contact your supervisor. % else:
Please review the updated shift details. If you have any questions or conflicts, please contact your supervisor immediately. % endif
This is an automated message from GuardLink Shift Management System




🚨 EMERGENCY ALERT 🚨





${object.title}

Priority: ${object.priority.upper()}



                        % if object.site_id:


                            Location:
                            ${object.site_id.name}

                        % endif


                            Issued:
                            ${format_datetime(object.broadcast_datetime, dt_format='medium')}



                            Issued By:
                            ${object.issued_by.name}




Emergency Details:


                        ${object.message}


                    % if object.action_required:



⚠ Action Required:

${object.action_required}

                    % endif




If this is a life-threatening emergency, call 911 immediately!






                            URGENT - IMMEDIATE ATTENTION REQUIRED



                            GuardLink Emergency Notification System

div.table:


    Key Number:
    ${object.key_number}

% if object.description:


    Description:
    ${object.description}

% endif
% if object.site_id:


    Site:
    ${object.site_id.name}

% endif

Package ID: ${object.name}
% if object.tracking_number:
Tracking Number: ${object.tracking_number}
% endif
Package Type: ${object.package_type.replace('_', ' ').title()}
Received Date: ${format_datetime(object.received_date, dt_format='d MMMM Y HH:mm', tz='UTC')}
Collected Date: ${format_datetime(object.pickup_date, dt_format='d MMMM Y HH:mm', tz='UTC') if object.pickup_date else 'N/A'}
% if ctx.get('collector_name'):
Collected By: ${ctx.get('collector_name')}
% endif % if ctx.get('relationship'):
Relationship: ${ctx.get('relationship')}
% endif % if ctx.get('guard_name'):
Guard on Duty: ${ctx.get('guard_name')}
% endif % if ctx.get('id_verified'):
ID Verified:
✓ Yes
% endif
